extends SceneTree
# Scratch capture: the town playground on one map, from several RTS camera
# distances (the default battle camera's 55 m among them).
# --play-out=DIR  --play-focus=x,z  --play-views=name:dist:pitch:yaw;...

func _initialize() -> void:
	call_deferred("run")

func run() -> void:
	var out := "user://play"
	var focus := Vector3(-21.07, 0, 7.45)
	var views := [["close", 15.0, -42.0, 0.7], ["mid", 30.0, -40.5, 0.7], ["battle", 55.0, -44.1, 0.7]]
	for arg in OS.get_cmdline_user_args():
		if arg.begins_with("--play-out="):
			out = arg.get_slice("=", 1)
		if arg.begins_with("--play-focus="):
			var f := arg.get_slice("=", 1).split(",")
			focus = Vector3(float(f[0]), 0, float(f[1]))
		if arg.begins_with("--play-views="):
			views = []
			for v in arg.get_slice("=", 1).split(";"):
				var p := v.split(":")
				views.append([p[0], float(p[1]), float(p[2]), float(p[3])])
	DirAccess.make_dir_recursive_absolute(out)
	var game = load("res://main.tscn").instantiate()
	root.add_child(game)
	current_scene = game
	while game.world == null or game.world.time < 2.0:
		await process_frame
	var world = game.world
	if world.director:
		world.director.active = false
	for view in views:
		world.cam.cam.rotation = Vector3.ZERO
		world.cam.dist = view[1]
		world.cam.target_dist = view[1]
		world.cam.pitch_deg = view[2]
		world.cam.yaw = view[3]
		world.cam.focus_pos = focus
		world.cam._apply()
		for frame in 90:
			await process_frame
		while world.structure_view != null and world.structure_view.warming():
			await process_frame
		await RenderingServer.frame_post_draw
		root.get_texture().get_image().save_png(out.path_join(String(view[0]) + ".png"))
		print("PLAYVIEW ", view[0])
	quit()
